&reftitle.description;
public Yaf_View_SimpleYaf_View_Simple::setScriptPath stringtemplate_dir
Establece el directorio en el que se buscan las plantillas.

&reftitle.parameters;


  template_dir


    El directorio donde se guardan los scripts de plantilla.

  &reftitle.examples;

   Ejemplo de Yaf_View_Simple::setScriptPath


<?php
class IndexController extends Yaf_Controller_Abstract
{
    public function indexAction()
    {
        /* renderiza plantillas desde otro directorio */
        $this->getView()->setScriptPath(APPLICATION_PATH . "/modules/admin/views");

        $this->getView()->display("dashboard/index.phtml");

        return false; // we rendered ourselves, skip auto-rendering
    }
}
?>
